#!/bin/bash
# Test script for complete WIRE2 MVP flow

set -e

GREEN='\033[0;32m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
NC='\033[0m'

BASE_URL="http://localhost:8000"
USER_ID="user_alice_smith"
APPROVER_ID="user_bob_jones"

echo -e "${GREEN}🧪 Testing WIRE2 MVP Complete Flow${NC}"
echo ""

# Step 1: Health Check
echo -e "${YELLOW}Step 1: Health Check${NC}"
HEALTH=$(curl -s "$BASE_URL/health")
if echo "$HEALTH" | grep -q "healthy"; then
    echo -e "${GREEN}✓ Backend is healthy${NC}"
else
    echo -e "${RED}✗ Backend health check failed${NC}"
    echo "$HEALTH"
    exit 1
fi

# Step 2: Get Beneficiaries (need one to create intent)
echo -e "\n${YELLOW}Step 2: Get Beneficiaries${NC}"
BENEFICIARIES=$(curl -s -H "X-USER-ID: $USER_ID" "$BASE_URL/api/wire/beneficiaries")
BENEF_ID=$(echo "$BENEFICIARIES" | grep -o '"id":"[^"]*"' | head -1 | cut -d'"' -f4)
if [ -z "$BENEF_ID" ]; then
    echo -e "${RED}✗ No beneficiaries found. Seeding may be needed.${NC}"
    exit 1
fi
echo -e "${GREEN}✓ Found beneficiary: $BENEF_ID${NC}"

# Step 3: Create Intent
echo -e "\n${YELLOW}Step 3: Create Intent${NC}"
INTENT_RESPONSE=$(curl -s -X POST \
    -H "X-USER-ID: $USER_ID" \
    -H "Content-Type: application/json" \
    -d "{
        \"railsType\": \"WIRE\",
        \"amountMinor\": \"1000000\",
        \"currency\": \"USD\",
        \"beneficiaryId\": \"$BENEF_ID\",
        \"purpose\": \"Test payment\"
    }" \
    "$BASE_URL/api/wire/intents")

INTENT_ID=$(echo "$INTENT_RESPONSE" | grep -o '"id":"[^"]*"' | head -1 | cut -d'"' -f4)
if [ -z "$INTENT_ID" ]; then
    echo -e "${RED}✗ Failed to create intent${NC}"
    echo "$INTENT_RESPONSE"
    exit 1
fi
echo -e "${GREEN}✓ Created intent: $INTENT_ID${NC}"

# Step 4: Generate Challenge
echo -e "\n${YELLOW}Step 4: Generate Voice Challenge${NC}"
CHALLENGE_RESPONSE=$(curl -s -X POST \
    -H "X-USER-ID: $USER_ID" \
    -H "Content-Type: application/json" \
    -d "{\"language\": \"EN\"}" \
    "$BASE_URL/api/wire/intents/$INTENT_ID/challenge")

CHALLENGE_ID=$(echo "$CHALLENGE_RESPONSE" | grep -o '"id":"[^"]*"' | head -1 | cut -d'"' -f4)
CHALLENGE_TEXT=$(echo "$CHALLENGE_RESPONSE" | grep -o '"challengeText":"[^"]*"' | head -1 | cut -d'"' -f4)
if [ -z "$CHALLENGE_ID" ]; then
    echo -e "${RED}✗ Failed to generate challenge${NC}"
    echo "$CHALLENGE_RESPONSE"
    exit 1
fi
echo -e "${GREEN}✓ Generated challenge: $CHALLENGE_ID${NC}"
echo "  Challenge text: ${CHALLENGE_TEXT:0:50}..."

# Step 5: Submit Proof (with transcript - MVP mode)
echo -e "\n${YELLOW}Step 5: Submit Voice Proof${NC}"
PROOF_RESPONSE=$(curl -s -X POST \
    -H "X-USER-ID: $USER_ID" \
    -H "Content-Type: application/json" \
    -d "{
        \"channel\": \"BROWSER\",
        \"transcript\": \"$CHALLENGE_TEXT\",
        \"deviceMetadataJson\": {
            \"audioBuffer\": \"dGVzdF9hdWRpb19kYXRh\",
            \"userAgent\": \"test-agent\"
        }
    }" \
    "$BASE_URL/api/wire/challenges/$CHALLENGE_ID/proof")

PROOF_ID=$(echo "$PROOF_RESPONSE" | grep -o '"id":"[^"]*"' | head -1 | cut -d'"' -f4)
if [ -z "$PROOF_ID" ]; then
    echo -e "${RED}✗ Failed to submit proof${NC}"
    echo "$PROOF_RESPONSE"
    exit 1
fi
echo -e "${GREEN}✓ Submitted proof: $PROOF_ID${NC}"

# Step 6: Make Approval Decision
echo -e "\n${YELLOW}Step 6: Make Approval Decision${NC}"
DECISION_RESPONSE=$(curl -s -X POST \
    -H "X-USER-ID: $APPROVER_ID" \
    -H "Content-Type: application/json" \
    -d "{
        \"action\": \"APPROVE\",
        \"proofId\": \"$PROOF_ID\"
    }" \
    "$BASE_URL/api/wire/intents/$INTENT_ID/decision")

APPROVAL_TOKEN=$(echo "$DECISION_RESPONSE" | grep -o '"approvalToken":"[^"]*"' | head -1 | cut -d'"' -f4)
if [ -z "$APPROVAL_TOKEN" ]; then
    echo -e "${YELLOW}⚠ No approval token (may need more approvals)${NC}"
    echo "$DECISION_RESPONSE"
else
    echo -e "${GREEN}✓ Got approval token${NC}"
fi

# Step 7: Execute Intent (if we have approval token)
if [ ! -z "$APPROVAL_TOKEN" ]; then
    echo -e "\n${YELLOW}Step 7: Execute Intent${NC}"
    IDEMPOTENCY_KEY="test_$(date +%s)"
    EXECUTE_RESPONSE=$(curl -s -X POST \
        -H "X-USER-ID: $USER_ID" \
        -H "X-POSE-APPROVAL: $APPROVAL_TOKEN" \
        -H "X-Idempotency-Key: $IDEMPOTENCY_KEY" \
        -H "Content-Type: application/json" \
        "$BASE_URL/api/wire/intents/$INTENT_ID/execute")
    
    EXEC_STATUS=$(echo "$EXECUTE_RESPONSE" | grep -o '"status":"[^"]*"' | head -1 | cut -d'"' -f4)
    if [ "$EXEC_STATUS" = "EXECUTED" ]; then
        echo -e "${GREEN}✓ Intent executed successfully${NC}"
    else
        echo -e "${YELLOW}⚠ Execution status: $EXEC_STATUS${NC}"
        echo "$EXECUTE_RESPONSE"
    fi
else
    echo -e "\n${YELLOW}Step 7: Execute Intent (skipped - no approval token)${NC}"
fi

# Step 8: Verify Event Chain
echo -e "\n${YELLOW}Step 8: Verify Event Chain${NC}"
EVENTS_RESPONSE=$(curl -s -H "X-USER-ID: $USER_ID" "$BASE_URL/api/wire/intents/$INTENT_ID/events")
EVENT_COUNT=$(echo "$EVENTS_RESPONSE" | grep -o '"seq":[0-9]*' | wc -l | tr -d ' ')
